// Fix string cleaning function to preserve normal symbols, emojis, line breaks, spaces
function replace_me(s) {
  return typeof s === "string"
    ? s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    : s;
}

// Process all input items and clean specified fields
for (const item of $input.all()) {
  item.json.post_content = replace_me(item.json.post_content);
  item.json.prev_ttl = replace_me(item.json.prev_ttl);
  item.json.prev_desc = replace_me(item.json.prev_desc);
}

return $input.all();
